text:
  "dDurationMs": 1151,
  "segs": [ {
    "utf8": "還是你要接受我的"
  } ]
}, {
  "tStartMs": 2193574,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "所以我就覺得和而不同很重要"
  } ]
}, {
  "tStartMs": 2195676,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "就是因為我就是跟你不一樣"
  } ]
}, {
  "tStartMs": 2197578,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "我就是不喜歡吃那麼甜"
  } ]
}, {
  "tStartMs": 2200381,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "但是我們都是自由民主"
  } ]
}, {
  "tStartMs": 2202066,
  "dDurationMs": 601,
  "segs": [ {
    "utf8": "OK"
  } ]
}, {
  "tStartMs": 2202667,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "我們有一個底線大家都"
  } ]
}, {
  "tStartMs": 2203868,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "沒錯"
  } ]
}, {
  "tStartMs": 2204569,
  "dDurationMs": 2602,
  "segs": [ {
    "utf8": "然後就是因為我們不同才有意義"
  } ]
}, {
  "tStartMs": 2207171,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "沒有不同就沒有意義了"
  } ]
}, {
  "tStartMs": 2208472,
  "dDurationMs": 1202,
  "segs": [ {
    "utf8": "我覺得像運動"
  } ]
}, {
  "tStartMs": 2209674,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "我覺得運動的興趣的培養"
  } ]
}, {
  "tStartMs": 2211576,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "其實就是一種競爭"
  } ]
}, {
  "tStartMs": 2212877,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "然後也是一種人格的養成"
  } ]
}, {
  "tStartMs": 2214779,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "是 我要贏 我要贏球"
  } ]
}, {
  "tStartMs": 2216280,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "我就是跟你不一樣"
  } ]
}, {
  "tStartMs": 2217281,
  "dDurationMs": 1685,
  "segs": [ {
    "utf8": "我球隊的風格就是跟你不同"
  } ]
}, {
  "tStartMs": 2218966,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "如果沒有分球隊"
  } ]
}, {
  "tStartMs": 2219867,
  "dDurationMs": 2903,
  "segs": [ {
    "utf8": "那對我來說運動那個競技感就沒有了"
  } ]
}, {
  "tStartMs": 2222770,
  "dDurationMs": 1251,
  "segs": [ {
    "utf8": "就是兩個城市"
  } ]
}, {
  "tStartMs": 2224021,
  "dDurationMs": 851,
  "segs": [ {
    "utf8": "兩個代表的球隊"
  } ]
}, {
  "tStartMs": 2224872,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "或兩個學校代表的球隊"
  } ]
}, {
  "tStartMs": 2226274,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "跟你拚個你死我活這樣子"
  } ]
}, {
  "tStartMs": 2228476,
  "dDurationMs": 2702,
  "segs": [ {
    "utf8": "那個競爭其實在現代社會是非常重要的"
  } ]
}, {
  "tStartMs": 2231178,
  "dDurationMs": 301,
  "segs": [ {
    "utf8": "OK"
  } ]
}, {
  "tStartMs": 2231479,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "所以有時候就是過猶不及"
  } ]
}, {
  "tStartMs": 2233581,
  "dDurationMs": 917,
  "segs": [ {
    "utf8": "有些人會覺得說 "
  } ]
}, {
  "tStartMs": 2234498,
  "dDurationMs": 1769,
  "segs": [ {
    "utf8": "我們覺得大家都和平"
  } ]
}, {
  "tStartMs": 2236267,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "大家都不要吵了"
  } ]
}, {
  "tStartMs": 2237168,
  "dDurationMs": 2335,
  "segs": [ {
    "utf8": "但又有一種就是說 "
  } ]
}, {
  "tStartMs": 2239503,
  "dDurationMs": 1652,
  "segs": [ {
    "utf8": "已經極端到兩邊吵到"
  } ]
}, {
  "tStartMs": 2241155,
  "dDurationMs": 1618,
  "segs": [ {
    "utf8": "已經是不只是肉體的拼搏"
  } ]
}, {
  "tStartMs": 2242773,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "都已經要噴血了"
  } ]
}, {
  "tStartMs": 2243774,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "那也不對"
  } ]
}, {
  "tStartMs": 2244475,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "所以就是明明中間"
  } ]
}, {
  "tStartMs": 2245676,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "它是有一個common就是說"
  } ]
}, {
  "tStartMs": 2247178,
  "dDurationMs": 1501,
  "segs": [ {
    "utf8": "我們可以大家都接受"
  } ]
}, {
  "tStartMs": 2248679,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "某一些基本的價值觀"
  } ]
}, {
  "tStartMs": 2250581,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "在這個基本的價值觀之上"
  } ]
}, {
  "tStartMs": 2252366,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "我們大家彼此互相競爭"
  } ]
}, {
  "tStartMs": 2253968,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "所以我就覺得保留每一個的文化"
  } ]
}, {
  "tStartMs": 2256070,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "眷村的文化對我來說也是文化"
  } ]
}, {
  "tStartMs": 2258372,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "日本時代的文化也是文化"
  } ]
}, {
  "tStartMs": 2260374,
  "dDurationMs": 2403,
  "segs": [ {
    "utf8": "威權時代大家抵抗也是文化"
  } ]
}, {
  "tStartMs": 2262777,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "文化就是一種生活方式"
  } ]
}, {
  "tStartMs": 2264679,
  "dDurationMs": 2602,
  "segs": [ {
    "utf8": "沒有人規定台北是一種生活方式"
  } ]
}, {
  "tStartMs": 2267281,
  "dDurationMs": 1018,
  "segs": [ {
    "utf8": "台北的特色就是 "
  } ]
}, {
  "tStartMs": 2268299,
  "dDurationMs": 1068,
  "segs": [ {
    "utf8": "它有那麼多種"
  } ]
}, {
  "tStartMs": 2269367,
  "dDurationMs": 2102,
  "segs": [ {
    "utf8": "不同的生活方式參雜在一起"
  } ]
}, {
  "tStartMs": 2271469,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "而且有可能這兩個參雜在一起之後"
  } ]
}, {
  "tStartMs": 2273371,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "雖然兩個互相競爭"
  } ]
}, {
  "tStartMs": 2274372,
  "dDurationMs": 1668,
  "segs": [ {
    "utf8": "結果生產了出第三種 "
  } ]
}, {
  "tStartMs": 2276040,
  "dDurationMs": 1335,
  "segs": [ {
    "utf8": "不同的生活方式"
  } ]
}, {
  "tStartMs": 2277375,
  "dDurationMs": 800,
  "segs": [ {
    "utf8": "有可能"
  } ]
}, {
  "tStartMs": 2278175,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "我覺得這就是台北的特色"
  } ]
}, {
  "tStartMs": 2279677,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "就是台北應該要呈現"
  } ]
